head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05009";
scwin.form = null;
scwin.maxLenCheckVars = undefined;
scwin.maxLenCheckNames = undefined;
scwin.maxLenCheckMax = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();
        try {
            if ($c.util.getComponent('dma_RegisterReq').get('facevalTotamtDsp')== null) {
                for (let i = 0; i < (console.warn("[sdd] unresolved:dmap-member:" + "facevalTotamtDsp @ dma_RegisterReq.facevalTotamtDsp"), $c.util.getComponent('dma_RegisterReq')).length; i++) {

                }
            } else {

            }
        } catch (err2) { $c.exception.handleError(err2, { notify: 'none', context: 'jldfil05009' }); return; }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05009.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05009' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.maxLenCheckVars =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05009' }); }

try { scwin.maxLenCheckNames =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05009' }); }

try { scwin.maxLenCheckMax =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05009' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05009.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_PrelistPageSearch_onclick
 * @description btn_PrelistPageSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_PrelistPageSearch_onclick = async function(e){
    try {
        await scwin.prelistPageSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05009.btn_PrelistPageSearch_onclick' }); }
};

/**
 * @method
 * @name ipt_isuexerRnd_onclick
 * @description ipt_isuexerRnd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isuexerRnd_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05009.ipt_isuexerRnd_onclick' }); }
};

/**
 * @method
 * @name ipt_facevalTotamt_onclick
 * @description ipt_facevalTotamt 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_facevalTotamt_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05009.ipt_facevalTotamt_onclick' }); }
};

/**
 * @method
 * @name ipt_facevalTotamt_onkeyup
 * @description ipt_facevalTotamt 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_facevalTotamt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05009.ipt_facevalTotamt_onkeyup' }); }
};

/**
 * @method
 * @name btn_Edit789_onclick
 * @description btn_Edit789 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Edit789_onclick = async function(e){
    try {
        await scwin.edit789()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05009.btn_Edit789_onclick' }); }
};

/**
 * @method
 * @name btn_Delete789_onclick
 * @description btn_Delete789 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete789_onclick = function(e){
    try {
        fn_Delete789()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05009.btn_Delete789_onclick' }); }
};

/**
 * @method
 * @name btn_UpdateLastPage_onclick
 * @description btn_UpdateLastPage 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_UpdateLastPage_onclick = function(e){
    try {
        fn_UpdateLastPage()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05009.btn_UpdateLastPage_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadForm(r["isuexerDd"], r["isuexerRnd"], r["disclsDd"], r["isuTpCd"], r["corpbndKindDsc"], r["facevalTotamt"], r["expDd"], r["remk"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.prelistEtcForm || { elements: [] });
        if (($c.util.getComponent('dma_RegisterReq').get('nowPage')) > ($c.util.getComponent('dma_RegisterReq').get('billLstSaveStatCd'))) {
            return;
        }
        scwin.onloadDataSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05009c.onload" });
    }
};

/**
 * @method
 * @name onloadDataSet
 * @description onload Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.onloadDataSet = function () {
    /* empty */
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/prelistEtc.do",
        ref: "dma_RegisterReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {String} isuexerDd isuexerDd
 * @param {*} isuexerRnd isuexerRnd
 * @param {String} disclsDd disclsDd
 * @param {String} isuTpCd isuTpCd
 * @param {*} corpbndKindDsc corpbndKindDsc
 * @param {*} facevalTotamt facevalTotamt
 * @param {String} expDd expDd
 * @param {*} remk remk
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (isuexerDd, isuexerRnd, disclsDd, isuTpCd, corpbndKindDsc, facevalTotamt, expDd, remk) {
    $c.util.getComponent('dma_RegisterReq').set('isuexerDdCheck', $c.date.dateUnFormat(isuexerDd));
    $c.util.getComponent('dma_RegisterReq').set('isuexerRndCheck', isuexerRnd);
    $c.util.getComponent('cal_isuexerDd').setValue($c.date.dateUnFormat(isuexerDd));
    $c.util.getComponent('ipt_isuexerRnd').setValue($c.date.dateUnFormat(isuexerRnd));
    $c.util.getComponent('cal_disclsDd').setValue($c.date.dateUnFormat(disclsDd));
    (($c.util.getComponent('slc_isuTpCd'))?.setValue?.(isuTpCd));
    $c.util.getComponent('ipt_corpbndKindDsc').setValue(corpbndKindDsc);
    $c.util.getComponent('ipt_facevalTotamt').setValue($c.num.formatNumber(facevalTotamt));
    $c.util.getComponent('cal_expDd').setValue($c.date.dateUnFormat(expDd));
    $c.util.getComponent('ipt_remk').setValue(remk);
    scwin.onloadDataSet();
};

/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    if ($c.util.getComponent('ipt_isuexerRnd').getValue().length <= 0 || $c.util.getComponent('ipt_isuexerRnd').getValue()=== "0") {
        await $c.win.alert("회차를 정확히 입력해주십시요.");
        $c.util.getComponent("ipt_isuexerRnd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if ($c.util.getComponent('cal_isuexerDd').getValue().length !== 8) {
        await $c.win.alert("발행일을 정확히 입력해주십시요.");
        $c.util.getComponent("cal_isuexerDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if ($c.util.getComponent('cal_disclsDd').getValue().length !== 8) {
        await $c.win.alert("공시일을 정확히 입력해주십시요.");
        $c.util.getComponent("cal_disclsDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if ($c.util.getComponent('cal_expDd').getValue().length !== 8) {
        await $c.win.alert("만기일을 정확히 입력해주십시요.");
        $c.util.getComponent("cal_expDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (!await (async () => { const vars = scwin.maxLenCheckVars || []; const names =  scwin.maxLenCheckNames || []; const maxes =  scwin.maxLenCheckMax || []; for (let i = 0; i < vars.length; i++) { const c = $c.util.getComponent(vars[i]); if (!c || !c.getValue) { continue; } const len = $c.str.getByteLength(String(c.getValue() ?? "")); const max = Number(maxes[i]) || 0; if (max && len > max) { await $c.win.alert(String(names[i]) + "의 최대길이(" + max + ")를 \n" + (len - max) + " Byte 만큼 초과하였습니다.\n수정후 저장하세요"); if (c.setFocus) { c.setFocus(); } return false; } } return true; })()) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name setDataMergeDate
 * @description set Data Merge Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataMergeDate = function () {
    /* empty */
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (await scwin.vailidationLn() === false) {
        return;
    }
    scwin.setDataMergeDate();
    scwin.form.action = '/list/prelistEtc.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistRegEtc');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name setInitData
 * @description set Init Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setInitData = function () {
    $c.util.getComponent('cal_isuexerDd').setValue("20080930");
    $c.util.getComponent('ipt_isuexerRnd').setValue("1");
    $c.util.getComponent('cal_disclsDd').setValue("20080930");
    $c.util.getComponent('ipt_corpbndKindDsc').setValue("1234222222");
    $c.util.getComponent('cal_expDd').setValue("20080930");
    $c.util.getComponent('ipt_remk').setValue("1234");
    scwin.onloadDataSet();
};

/**
 * @method
 * @name prelistPageSearch
 * @description prelist Page Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistPageSearch = async function () {
    scwin.form.action       = '/list/prelistPage.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistPageSearch');
    await moveUrl('/list/prelistPage.do', {});

};

/**
 * @method
 * @name edit789
 * @description edit789 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edit789 = async function () {
    if(!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) return ;

    if(($c.util.getComponent('cal_isuexerDd').getValue() == null ? '' : String($c.util.getComponent('cal_isuexerDd').getValue())) === '' || $c.util.getComponent('cal_isuexerDd').length === 0 ||
        ($c.util.getComponent('ipt_isuexerRnd').getValue() == null ? '' : String($c.util.getComponent('ipt_isuexerRnd').getValue())) === '' || $c.util.getComponent('ipt_isuexerRnd').length === 0 ) {
        await $c.win.alert("수정하시려면, 리스트에서 선택후 수정하세요.");
        return ;
    }

    if($c.util.getComponent('dma_RegisterReq').get('isuexerDdCheck')!== $c.util.getComponent('cal_isuexerDd').getValue()) {
        await $c.win.alert("발행일을 수정하시면 자료를 갱신 할 수 없습니다.");
        return;
    }

    if($c.util.getComponent('dma_RegisterReq').get('isuexerRndCheck')!== $c.util.getComponent('ipt_isuexerRnd').getValue()) {
        await $c.win.alert("회차를 수정하시면 자료를 갱신 할 수 없습니다.");
        return;
    }

    $c.util.getComponent('dma_RegisterReq').set('transKind', 1); // 신규: 0 , 수정 : 1 , 삭제 : 3

    await scwin.register() ;

};

/**
 * @method
 * @name new789
 * @description new789 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new789 = async function () {
    if(!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) return ;

    $c.util.getComponent('dma_RegisterReq').set('transKind', 0); // 신규: 0 , 수정 : 1 , 삭제 : 3

    // ??? 조회 목록중에 청구일련번호 같은것이 있는지 체크 필

    await scwin.register() ;

};
